package app.dayflow;
import android.widget.*;
import com.google.android.material.textfield.TextInputEditText;
import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.select.Elements;
import org.json.*;
import java.io.*;
import java.net.*;
import java.time.*;
import java.util.*;

/** jsoup parses saved HTML without executing page scripts or sending account cookies. */
final class WebImports {
 static void show(MainActivity a){LinearLayout page=a.fullPage("网页与课表导入",a::home);page.addView(Ui.text(a,"导入网页、课表或日历",22,true));TextInputEditText url=Ui.field(a,page,"公开网页 / ICS 地址（可选）","",false),text=Ui.field(a,page,"粘贴 HTML、CSV 或 ICS 内容","",true);page.addView(Ui.help(a,"仅读取你填写的页面，不接收账号或登录Cookie。教务系统可先用浏览器导出HTML再导入；规则无法确定的表格先转正文，由你或AI确认。"));page.addView(Ui.button(a,"读取地址",true,()->{String address=url.getText().toString();final String[] result={null};a.job(()->{result[0]=fetch(address);return "内容已读取，请确认导入方式";},()->preview(a,result[0]));}));page.addView(Ui.button(a,"解析粘贴内容",false,()->{String body=text.getText().toString();if(body.trim().isEmpty()){a.message("请先粘贴内容");return;}preview(a,body);}));page.addView(Ui.button(a,"选择 HTML / CSV / ICS 文件",false,()->a.pickFile(103,"*/*")));}
 static String fetch(String input)throws Exception{URL target=new URL(Network.endpoint(input,true));for(int i=0;i<4;i++){HttpURLConnection connection=(HttpURLConnection)target.openConnection();connection.setConnectTimeout(15000);connection.setReadTimeout(30000);connection.setInstanceFollowRedirects(false);try{int status=connection.getResponseCode();if(status>=300&&status<400){String next=connection.getHeaderField("Location");if(next==null)throw new IOException("网页重定向无目标");URL redirect=new URL(target,next);Network.endpoint(redirect.toString(),true);if(!redirect.getHost().equalsIgnoreCase(target.getHost()))throw new IOException("地址重定向至其他网站，请填写最终网址");target=redirect;continue;}if(status!=200)throw new IOException("网页HTTP "+status+"，可能需要浏览器登录后导出文件");try(InputStream in=connection.getInputStream()){return Network.read(in,1024*1024);}}finally{connection.disconnect();}}throw new IOException("页面重定向次数过多");}
 private static void preview(MainActivity a,String body){LinearLayout page=a.fullPage("校对导入内容",()->show(a));String plain=body.trim().startsWith("<")?Jsoup.parse(body).body().text():body;TextView preview=Ui.text(a,plain.substring(0,Math.min(plain.length(),3000)),15,false);preview.setTextIsSelectable(true);page.addView(preview);page.addView(Ui.button(a,"解析为日程 / 课程预览",true,()->{final JSONArray[] rows={null};a.job(()->{rows[0]=Imports.timetable(body);return "已解析 "+rows[0].length()+" 项，尚未加入日程";},()->a.importPreview(rows[0]));}));page.addView(Ui.button(a,"正文放入收集箱继续校对",false,()->{String content=plain.length()>12000?plain.substring(0,12000):plain;a.showCaptureText(content);}));page.addView(Ui.help(a,"ICS每次展开一年以内，最大4000项。重复订阅用UID与发生时刻去重，导入不覆盖已编辑事项。复杂表格的跨行合并或未知节次需人工/AI校对。"));}
 static JSONArray html(String source)throws Exception{Document doc=Jsoup.parse(source);String csv=tableCsv(doc);if(!csv.isEmpty())return Imports.timetable(csv);String plain=doc.body().text();if(plain.length()>12000)plain=plain.substring(0,12000);if(plain.trim().isEmpty())throw new Exception("网页没有可读取的正文");return new JSONArray().put(Data.make("inbox",doc.title().isEmpty()?"网页课表 · 待确认":doc.title()).put("content",plain).put("source","HTML导入·需校对").put("confirmation_status","pending"));}
 private static String column(String value){String key=value.trim().toLowerCase(Locale.ROOT).replaceAll("\\s+","");String[][] names={{"title","课程名称","课程名","课程","事项"},{"weekday","星期","星期几","周几"},{"start_time","开始时间","上课时间"},{"end_time","结束时间","下课时间"},{"start_date","开始日期","起始日期"},{"end_date","结束日期","截止日期"},{"weeks","单双周","周次"},{"location","教室","地点"}};for(String[] list:names)for(String alias:list)if(key.equals(alias))return list[0];return key;}
 private static String quote(String value){return "\""+value.replace("\"","\"\"")+"\"";}
 private static String tableCsv(Document doc)throws Exception{for(Element table:doc.select("table")){Elements rows=table.select("tr");if(rows.size()<2)continue;if(rows.size()>500)throw new Exception("表格行数过多，请拆分导入");Elements cells=rows.get(0).select("th,td");List<String> headers=new ArrayList<>();for(Element cell:cells)headers.add(column(cell.text()));if(!headers.containsAll(Arrays.asList("title","weekday","start_time","start_date","end_date")))continue;StringBuilder out=new StringBuilder();List<String> canonical=Arrays.asList("title","weekday","start_time","end_time","start_date","end_date","weeks","location");out.append(String.join(",",canonical)).append('\n');for(int i=1;i<rows.size();i++){Elements values=rows.get(i).select("td,th");if(values.size()!=headers.size())throw new Exception("课表含合并单元格，请转正文或截图识别");for(int c=0;c<canonical.size();c++){if(c>0)out.append(',');int index=headers.indexOf(canonical.get(c));String value=index<0?canonical.get(c).equals("weeks")?"all":"":values.get(index).text();if(canonical.get(c).equals("weekday")){value=value.replace("星期","").replace("周","");if(value.length()==1&&"一二三四五六日天".contains(value))value=Integer.toString(Math.min(7,"一二三四五六日天".indexOf(value)+1));}if(canonical.get(c).equals("weeks")){if(value.equals("单"))value="odd";if(value.equals("双"))value="even";if(value.equals("全部")||value.isEmpty())value="all";}out.append(quote(value));}out.append('\n');}return out.toString();}return "";}
}
